SELECT  FROM crm_project
WHERE tenant_id=#{tenantId}
AND (project_code LIKE CONCAT('%',#{keyword},'%') OR project_name LIKE CONCAT('%',#{keyword},'%'))
AND status=#{status}
ORDER BY id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM crm_project WHERE tenant_id=#{tenantId}
AND (project_code LIKE CONCAT('%',#{keyword},'%') OR project_name LIKE CONCAT('%',#{keyword},'%'))
AND status=#{status}

