mapper.select:
SELECT  FROM crm_institution i
WHERE i.tenant_id=#{tenantId} AND i.archived=0
AND (i.full_name LIKE CONCAT('%',#{keyword},'%') OR i.short_name LIKE CONCAT('%',#{keyword},'%') OR i.institution_no LIKE CONCAT('%',#{keyword},'%'))
AND i.status=#{status}
AND 1=0
AND i.id IN #{iid}
ORDER BY i.id LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM crm_institution i WHERE i.tenant_id=#{tenantId} AND i.archived=0
AND (i.full_name LIKE CONCAT('%',#{keyword},'%') OR i.short_name LIKE CONCAT('%',#{keyword},'%') OR i.institution_no LIKE CONCAT('%',#{keyword},'%'))
AND i.status=#{status}
AND 1=0
AND i.id IN #{iid}

SELECT COUNT(*) FROM crm_institution i WHERE i.tenant_id=#{tenantId} AND i.archived=0 AND i.status='ACTIVE'
AND 1=0
AND i.id IN #{iid}
